import os, sysimport numpy as npimport matplotlib.pyplot as pltimport h5py as h5pyimport scipy.interpolate as spisys.path.insert(0, "/home/raul/codes/global21cm/")import general as gendef beam_save_to_hdf5():		'''	a1: horiz, t=1m, h=0.5m	a2: horiz, t=1m, h=5m		a6: horiz, t=1m, h=50,000m		b1: vert, t=1m, h=0.5m	b2: vert, t=1m, h=5m		b6: vert, t=1m, h=50,000m	c1: horiz, single-layer, h=0.5m	c2: horiz, single-layer, h=5m		c6: horiz, single-layer, h=50,000m	d1: vert, single-layer, h=0.5m	d2: vert, single-layer, h=5m		d6: vert, single-layer, h=50,000m					e1: horiz, t=10m, h=0.5m	e2: horiz, t=10m, h=5m		e6: horiz, t=10m, h=50,000m					f1: vert, t=10m, h=0.5m	f2: vert, t=10m, h=5m		f6: vert, t=10m, h=50,000m		'''			for case1 in ['a','b','c','d','e','f']:          # compute separately a3-a6		for case2 in ['1','2','3','4','5','6']:  #['1','2','3','4','5','6']:			case = case1 + case2			name_folder = '/media/raul/SSD_4TB/FEKO_simulations/subsurface/' + case + '/'						f, AZ, EL, Et, Ep, g = gen.read_beam_FEKO(name_folder + case + '.out', 0)			f, s11               = gen.read_s11_FEKO(name_folder + case + '.out')                                                        			# Save RFI-flagged data			# ---------------------			with h5py.File(name_folder + case + '.hdf5', 'w') as hf:				hf.create_dataset('f',   data = f)				hf.create_dataset('AZ',  data = AZ)				hf.create_dataset('EL',  data = EL)				hf.create_dataset('Et',  data = Et)				hf.create_dataset('Ep',  data = Ep)				hf.create_dataset('g',   data = g)				hf.create_dataset('s11', data = s11)					return 0def beam_5kHz_save_to_hdf5(case):		'''	a5: horiz, t=1m, h=5km	a6: horiz, t=1m, h=50km		b5: vert, t=1m, h=5km	b6: vert, t=1m, h=50km	c5: horiz, single-layer, h=5km	c6: horiz, single-layer, h=50km	d5: vert, single-layer, h=5km	d6: vert, single-layer, h=50km		e5: horiz, t=10m, h=5km	e6: horiz, t=10m, h=50km			f5: vert, t=10m, h=5km	f6: vert, t=10m, h=50km		'''			name_folder = '/media/raul/SSD_RED_8TB/FEKO_simulations/subsurface/5kHz/'		#for case1 in ['b']:          #['a','b','c','d','e','f']: 		#for case2 in ['6']:  # ['5','6']:						#case = case1 + case2 + '_5kHz'				fs11, s11 = gen.read_s11_FEKO(name_folder + case + '.out')										f, AZ, EL, Et, Ep, g = gen.read_beam_FEKO(name_folder + case + '.out', 0, index_freq_min=0, index_freq_max=11900)	h1_s11 = s11[(fs11>=np.min(f)) & (fs11<=np.max(f))]	      	# Save RFI-flagged data	# ---------------------	with h5py.File(name_folder + case + '.hdf5', 'w') as hf:		hf.create_dataset('h1_f',   data = f)		hf.create_dataset('h1_AZ',  data = AZ)		hf.create_dataset('h1_EL',  data = EL)		hf.create_dataset('h1_Et',  data = Et)		hf.create_dataset('h1_Ep',  data = Ep)		hf.create_dataset('h1_g',   data = g)		hf.create_dataset('h1_s11', data = h1_s11)							f  = 0	AZ = 0	EL = 0	Et = 0	Ep = 0	g  = 0	f, AZ, EL, Et, Ep, g = gen.read_beam_FEKO(name_folder + case + '.out', 0, index_freq_min=11901, index_freq_max=23800)	h2_s11 = s11[(fs11>=np.min(f)) & (fs11<=np.max(f))]	      	# Save RFI-flagged data	# ---------------------	with h5py.File(name_folder + case + '.hdf5', 'r+') as hf:		hf.create_dataset('h2_f',   data = f)		hf.create_dataset('h2_AZ',  data = AZ)		hf.create_dataset('h2_EL',  data = EL)		hf.create_dataset('h2_Et',  data = Et)		hf.create_dataset('h2_Ep',  data = Ep)		hf.create_dataset('h2_g',   data = g)		hf.create_dataset('h2_s11', data = h2_s11)			return 0def DO_NOT_USE_beam_5kHz_save_to_hdf5():		'''	a5: horiz, t=1m, h=5km	a6: horiz, t=1m, h=50km		b5: vert, t=1m, h=5km	b6: vert, t=1m, h=50km	c5: horiz, single-layer, h=5km	c6: horiz, single-layer, h=50km	d5: vert, single-layer, h=5km	d6: vert, single-layer, h=50km		e5: horiz, t=10m, h=5km	e6: horiz, t=10m, h=50km			f5: vert, t=10m, h=5km	f6: vert, t=10m, h=50km		'''			name_folder = '/media/raul/SSD_RED_8TB/FEKO_simulations/subsurface/5kHz/'		for case1 in ['a']:          #['a','b','c','d','e','f']: 		for case2 in ['5']:  # ['5','6']:						case = case1 + case2 + '_5kHz'									fs11, s11 = gen.read_s11_FEKO(name_folder + case + '.out')			f, AZ, EL, Et, Ep, g = gen.read_beam_FEKO(name_folder + case + '.out', 0, index_freq_min=0, index_freq_max=23800)						        			# Save RFI-flagged data			# ---------------------			with h5py.File(name_folder + case + '.hdf5', 'w') as hf:				hf.create_dataset('f',   data = f)				hf.create_dataset('AZ',  data = AZ)				hf.create_dataset('EL',  data = EL)				hf.create_dataset('Et',  data = Et)				hf.create_dataset('Ep',  data = Ep)				hf.create_dataset('g',   data = g)				hf.create_dataset('s11', data = s11)					return 0def beam_read_hdf5(path_file, print_key='no'):		# path_file = home_folder + '/path/file.hdf5'	# Show keys (array names inside HDF5 file)	with h5py.File(path_file,'r') as hf:		if print_key == 'yes':			print([key for key in hf.keys()])		hfX   = hf.get('f')		f     = np.array(hfX)		hfX   = hf.get('AZ')		AZ    = np.array(hfX)				hfX   = hf.get('EL')		EL    = np.array(hfX)				hfX   = hf.get('Et')		Et    = np.array(hfX)						hfX   = hf.get('Ep')		Ep    = np.array(hfX)				hfX   = hf.get('g')		g     = np.array(hfX)						hfX   = hf.get('s11')		s11   = np.array(hfX)				return f, AZ, EL, Et, Ep, g, s11def beam_5kHz_read_hdf5(path_file, print_key='no'):		# path_file = home_folder + '/path/file.hdf5'	# Show keys (array names inside HDF5 file)	with h5py.File(path_file,'r') as hf:		if print_key == 'yes':			print([key for key in hf.keys()])		hfX    = hf.get('h1_f')		h1_f   = np.array(hfX)		hfX    = hf.get('h1_AZ')		h1_AZ  = np.array(hfX)				hfX    = hf.get('h1_EL')		h1_EL  = np.array(hfX)				hfX    = hf.get('h1_Et')		h1_Et  = np.array(hfX)						hfX    = hf.get('h1_Ep')		h1_Ep  = np.array(hfX)				hfX    = hf.get('h1_g')		h1_g   = np.array(hfX)						hfX    = hf.get('h1_s11')		h1_s11 = np.array(hfX)						hfX    = hf.get('h2_f')		h2_f   = np.array(hfX)		hfX    = hf.get('h2_AZ')		h2_AZ  = np.array(hfX)				hfX    = hf.get('h2_EL')		h2_EL  = np.array(hfX)				hfX    = hf.get('h2_Et')		h2_Et  = np.array(hfX)						hfX    = hf.get('h2_Ep')		h2_Ep  = np.array(hfX)				hfX    = hf.get('h2_g')		h2_g   = np.array(hfX)						hfX    = hf.get('h2_s11')		h2_s11 = np.array(hfX)					f   = np.concatenate((h1_f, h2_f))	AZ  = np.copy(h1_AZ)	EL  = np.copy(h1_EL)		Et  = np.concatenate((h1_Et,  h2_Et),  axis=0)	Ep  = np.concatenate((h1_Ep,  h2_Ep),  axis=0)	g   = np.concatenate((h1_g,   h2_g),   axis=0)	s11 = np.concatenate((h1_s11, h2_s11), axis=0)				return f, AZ, EL, Et, Ep, g, s11def beam_load(case,res):		'''	case: 'a1', 'a2', etc.	res: '10kHz' or '5kHz'		'''        	# Loading hdf5 beam		if res == '10kHz':		path_file = '/media/raul/SSD_RED_8TB/FEKO_simulations/subsurface/' + case + '/' + case + '.hdf5'		f, AZ, EL, Et, Ep, g, s11 = beam_read_hdf5(path_file)			elif res == '5kHz':		path_file = '/media/raul/SSD_RED_8TB/FEKO_simulations/subsurface/5kHz/' + case + '_5kHz.hdf5'		f, AZ, EL, Et, Ep, g, s11 = beam_5kHz_read_hdf5(path_file)					return f, AZ, EL, gdef beam_frequency_interpolation(f, g, interp_f_Hz=1000):		f_interp = np.arange(np.min(f), np.max(f)+(interp_f_Hz/2), interp_f_Hz)		len_f_interp = len(f_interp)	len_EL       = len(g[0,:,0])	len_AZ       = len(g[0,0,:])		g_interp = np.zeros((len_f_interp, len_EL, len_AZ))		for j in range(len_EL):		for i in range(len_AZ):						print([j,i])						d = g[:,j,i]			func = spi.interp1d(f, d, 'cubic')			d_interp = func(f_interp)			g_interp[:,j,i] = d_interp		return f_interp, g_interpdef beam_moving_average(f, g, halfwidth):	'''		halfwidth: half width of the rectangular (top hat) window, in number of raw channels. It could be 5, 10, 1000, etc.		'''		lenf = len(f)	ix = np.arange(lenf)	#hw  = 5 #10	ixl = ix-halfwidth	ixh = ix+halfwidth+1		ixl[ixl<0]    = 0	ixh[ixh>lenf] = lenf			# Binning beam	gb1 = np.zeros((lenf,91,360))	for i in range(lenf):				print(i)				ix_bin = np.arange(ixl[i],ixh[i])		x = g[ix_bin,:,:]		gb1[i,:,:] = np.mean(x, axis=0)	return ixl, ixh, gb1def beam_frequency_binning(f, g, new_f_centers):		ix = np.arange(len(f))		df = new_f_centers[1] - new_f_centers[0]		gb = np.zeros((len(new_f_centers), len(g[0,:,0]), len(g[0,0,:])))		for i in range(len(new_f_centers)):		print(i)		ix_bin = ix[(f >= (new_f_centers[i]-(df/2))) & (f < (new_f_centers[i]+(df/2)))]		x = g[ix_bin,:,:]		gb[i,:,:] = np.mean(x, axis=0)				return gbdef average_normalized_directivity(case,res):		'''		'e4','10kHz'		'''			f, AZ, EL, d = beam_load(case,res)	s  = gen.beam_solid_angle(f, AZ, EL, d)			fi, di = beam_frequency_interpolation(f, d, interp_f_Hz=1000)	si = gen.beam_solid_angle(fi, AZ, EL, di)			return f, d, s, fi, di, si